<main class="sf-editorial"><article class="sf-journal-body"><a href="<?= base_url('store/'.$settings->store_slug); ?>">← Back to the store</a><p class="sf-editorial-kicker"><?= htmlspecialchars($store->store_name??'Online store'); ?></p><h1><?= htmlspecialchars($site_content['privacy_heading']); ?></h1><?php if(!empty($site_content['contact_enabled'])): ?><p><a href="<?= base_url('store/'.$settings->store_slug.'/contact'); ?>">Contact this store ↗</a></p><?php endif; ?><div class="sf-journal-copy"><?= htmlspecialchars($site_content['privacy_body']); ?></div><?php if(!empty($settings->store_email)||!empty($settings->store_phone)||!empty($settings->store_address)): ?><section style="margin-top:32px"><h2>Contact this store</h2><?php if(!empty($settings->store_email)): ?><p><a href="mailto:<?= htmlspecialchars($settings->store_email,ENT_QUOTES); ?>"><?= htmlspecialchars($settings->store_email); ?></a></p><?php endif; ?><?php if(!empty($settings->store_phone)): ?><p><a href="tel:<?= preg_replace('/[^+0-9]/','',$settings->store_phone); ?>"><?= htmlspecialchars($settings->store_phone); ?></a></p><?php endif; ?><?php if(!empty($settings->store_address)): ?><p><?= nl2br(htmlspecialchars($settings->store_address)); ?></p><?php endif; ?></section><?php endif; ?></article></main>
